from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class RadDebugParamUpdateResponse(SchemaObject):
    operation_id = SchemaField(name='operation_id', not_null=True)
    status = SchemaField(name='status', not_null=True)
    error_message = SchemaField(name='error_message', optional=True)

    def __init__(self, operation_id, status, error_message):
        self.operation_id = operation_id
        self.status = status
        self.error_message = error_message

        super(RadDebugParamUpdateResponse, self).__init__()
